#include <stdio.h>

int main() {
    // 累加器初始为 0，for 循环走完后 sum 就包含 1 到 100 的和。
    int sum = 0;
    for (int i = 1; i <= 100; i++) {
        sum += i;
    }
    printf("%d\n", sum);
    return 0;
}
